#### Example 2: Evaluation Scorecard Calculator (Excel/TypeScript)

```typescript
// Evaluation scorecard implementation
export interface ScorecardInputs {
  // Dimension 1: User Interaction (0-10)
  userInteractionLevel: 0 | 3 | 7 | 10;  // 0=None, 3=Admin config, 7=Power user, 10=End user

  // Dimension 2: Security Risk (0-10) - inverted (higher = safer)
  clientSideDataExposure: 0 | 5 | 10;  // 0=PII/PHI, 5=Non-sensitive business data, 10=None
  xssRisk: 0 | 5 | 10;  // 0=High (user input rendering), 5=Moderate, 10=Low (no dynamic content)

  // Dimension 3: Implementation Cost (0-10)
  estimatedCostBackend: number;  // Dollar amount
  estimatedCostUI: number;  // Dollar amount

  // Dimension 4: Timeline Pressure (0-10)
  customerDeadlineMonths: number;  // Number of months

  // Dimension 5: Complexity (0-10)
  backendComplexity: 0 | 5 | 10;  // 0=Complex, 5=Moderate, 10=Simple
  uiComplexity: 0 | 5 | 10;

  // Dimension 6: Performance Impact (0-10)
  bundleSizeKB: number;
  apiCallsPerInteraction: number;

  // Dimension 7: Accessibility Requirement (0-10)
  wcagComplianceRequired: boolean;  // True = WCAG 2.2 AA mandatory

  // Dimension 8: Maintenance Burden (0-10)
  designSystemDependency: boolean;  // True = depends on DS updates
  crossBrowserTesting: boolean;  // True = requires multi-browser QA
}

export interface ScorecardResult {
  dimensionScores: {
    userInteraction: number;
    securityRisk: number;
    implementationCost: number;
    timelinePressure: number;
    complexity: number;
    performanceImpact: number;
    accessibilityRequirement: number;
    maintenanceBurden: number;
  };
  weightedScore: number;  // 0-100
  recommendation: 'backend-only' | 'evaluate-both' | 'ui-extension';
  rationale: string;
}

export function calculateScorecardScore(inputs: ScorecardInputs): ScorecardResult {
  // Dimension 1: User Interaction (weight: 3x)
  const userInteractionScore = inputs.userInteractionLevel;

  // Dimension 2: Security Risk (weight: 2x) - average of two sub-factors
  const securityRiskScore = (inputs.clientSideDataExposure + inputs.xssRisk) / 2;

  // Dimension 3: Implementation Cost (weight: 2x)
  const costRatio = inputs.estimatedCostUI / Math.max(inputs.estimatedCostBackend, 1);
  const implementationCostScore = costRatio < 1.5 ? 10 : (costRatio < 2.5 ? 5 : 0);

  // Dimension 4: Timeline Pressure (weight: 1x)
  const timelinePressureScore = inputs.customerDeadlineMonths > 6 ? 10 : (inputs.customerDeadlineMonths > 3 ? 5 : 0);

  // Dimension 5: Complexity (weight: 1x) - average backend and UI
  const complexityScore = (inputs.backendComplexity + inputs.uiComplexity) / 2;

  // Dimension 6: Performance Impact (weight: 1.5x)
  const bundleSizeScore = inputs.bundleSizeKB < 50 ? 10 : (inputs.bundleSizeKB < 100 ? 5 : 0);
  const apiCallScore = inputs.apiCallsPerInteraction < 3 ? 10 : (inputs.apiCallsPerInteraction < 6 ? 5 : 0);
  const performanceImpactScore = (bundleSizeScore + apiCallScore) / 2;

  // Dimension 7: Accessibility Requirement (weight: 2x)
  const accessibilityRequirementScore = inputs.wcagComplianceRequired ? 0 : 10;

  // Dimension 8: Maintenance Burden (weight: 1.5x)
  const dsMaintenanceScore = inputs.designSystemDependency ? 5 : 10;
  const browserTestingScore = inputs.crossBrowserTesting ? 5 : 10;
  const maintenanceBurdenScore = (dsMaintenanceScore + browserTestingScore) / 2;

  // Calculate weighted score
  const weightedScore = (
    (userInteractionScore * 3) +
    (securityRiskScore * 2) +
    (implementationCostScore * 2) +
    (timelinePressureScore * 1) +
    (complexityScore * 1) +
    (performanceImpactScore * 1.5) +
    (accessibilityRequirementScore * 2) +
    (maintenanceBurdenScore * 1.5)
  ) / 15;  // Total weight = 15

  // Determine recommendation
  let recommendation: 'backend-only' | 'evaluate-both' | 'ui-extension';
  let rationale: string;

  if (weightedScore < 60) {
    recommendation = 'backend-only';
    rationale = `Weighted score ${weightedScore.toFixed(1)} indicates backend-only extension is most appropriate. Key factors: ${getKeyFactors(inputs)}`;
  } else if (weightedScore < 76) {
    recommendation = 'evaluate-both';
    rationale = `Weighted score ${weightedScore.toFixed(1)} falls in ambiguous range. ARB review recommended to evaluate backend vs UI trade-offs.`;
  } else {
    recommendation = 'ui-extension';
    rationale = `Weighted score ${weightedScore.toFixed(1)} strongly indicates UI extension value. Proceed if application is React-ready.`;
  }

  return {
    dimensionScores: {
      userInteraction: userInteractionScore,
      securityRisk: securityRiskScore,
      implementationCost: implementationCostScore,
      timelinePressure: timelinePressureScore,
      complexity: complexityScore,
      performanceImpact: performanceImpactScore,
      accessibilityRequirement: accessibilityRequirementScore,
      maintenanceBurden: maintenanceBurdenScore
    },
    weightedScore,
    recommendation,
    rationale
  };
}

function getKeyFactors(inputs: ScorecardInputs): string {
  const factors: string[] = [];
  if (inputs.userInteractionLevel < 5) factors.push('low user interaction');
  if (inputs.xssRisk < 7) factors.push('security risk');
  if (inputs.estimatedCostUI / inputs.estimatedCostBackend > 2) factors.push('high UI cost');
  if (inputs.wcagComplianceRequired) factors.push('accessibility requirements');
  return factors.join(', ');
}

// Example usage
const texasEligibilityExample: ScorecardInputs = {
  userInteractionLevel: 3,  // Admin configuration
  clientSideDataExposure: 10,  // No PII/PHI in UI
  xssRisk: 10,  // No user input rendering
  estimatedCostBackend: 75000,
  estimatedCostUI: 180000,
  customerDeadlineMonths: 8,
  backendComplexity: 5,
  uiComplexity: 5,
  bundleSizeKB: 80,
  apiCallsPerInteraction: 2,
  wcagComplianceRequired: true,
  designSystemDependency: true,
  crossBrowserTesting: true
};

const result = calculateScorecardScore(texasEligibilityExample);
console.log(result);
// Output: { weightedScore: 58.3, recommendation: 'backend-only', ... }
```
